for _l, _v in ADMIN.items():
    assert len(_v) == len(ADMIN_KEYS), _l
    T[_l].extend(_v)

def nest(keys, values):
    out = {}
    for k, v in zip(keys, values):
        # capability keys contain dots (helper.offer_services): split only on the first dot
        # for the capabilities/capabilityHelp groups; i18next uses keySeparator '.', so those
        # are stored as nested objects matching t('progressiveAccess.capabilities.helper.offer_services').
        parts = k.split('.')
        cur = out
        for p in parts[:-1]:
            cur = cur.setdefault(p, {})
        cur[parts[-1]] = v
    return out

if __name__ == '__main__':
    root = os.path.join(os.path.dirname(__file__), '..', '..', '..', 'client', 'src', 'i18n', 'locales')
    for lng, vals in T.items():
        assert len(vals) == len(KEYS), (lng, len(vals), len(KEYS))
        p = os.path.join(root, lng, 'common.json')
        with open(p, encoding='utf-8') as f:
            data = json.load(f)
        data['progressiveAccess'] = nest(KEYS, vals)
        with open(p, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.write('\n')
    print('wrote', sorted(T))
